import React, { useState } from 'react';
import axios from 'axios'; // API request දාන්න axios පාවිච්චි කරනවා නම්

export default function ChangePassword({ studentId }) {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [message, setMessage] = useState('');

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    
    // අලුතින් ගහපු password දෙක සමානද බලනවා
    if (newPassword !== confirmPassword) {
      setMessage("❌ අලුත් Password දෙක සමාන නැත!");
      return;
    }

    try {
      // Backend API එකට දත්ත යැවීම
      const response = await axios.put('http://localhost:5000/api/student/change-password', {
        studentId: studentId,
        currentPassword: currentPassword,
        newPassword: newPassword
      });

      if (response.data.success) {
        setMessage("✅ Password එක සාර්ථකව වෙනස් කළා!");
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
      }
    } catch (error) {
      setMessage(`❌ ප්‍රශ්නයක් ඇත: ${error.response?.data?.message || error.message}`);
    }
  };

  return (
    <div style={{ maxWidth: '400px', padding: '20px', backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
      <h3 style={{ marginTop: 0, color: '#15803d' }}>Change Password</h3>
      
      {message && <p style={{ fontWeight: '600', fontSize: '13px' }}>{message}</p>}
      
      <form onSubmit={handlePasswordChange} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <div>
          <label style={{ display: 'block', fontSize: '13px', fontWeight: '600' }}>Current Password</label>
          <input type="password" required value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1' }} />
        </div>
        
        <div>
          <label style={{ display: 'block', fontSize: '13px', fontWeight: '600' }}>New Password</label>
          <input type="password" required value={newPassword} onChange={(e) => setNewPassword(e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1' }} />
        </div>
        
        <div>
          <label style={{ display: 'block', fontSize: '13px', fontWeight: '600' }}>Confirm New Password</label>
          <input type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1' }} />
        </div>
        
        <button type="submit" style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '10px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px' }}>
          Update Password
        </button>
      </form>
    </div>
  );
}
